tokens.css:
--color-bg: #faf8f6;
--color-surface: #ffffff;
--color-text: #1c1917;
--color-text-muted: #5f5852;
--color-border: #e6e0da;
--color-primary: #9a4a6b;
--color-on-primary: #ffffff;
--color-accent: #8b6b4a;
--color-on-accent: #ffffff;
--font-display: "Anton", system-ui, sans-serif;
--font-body: "Familjen Grotesk", system-ui, sans-serif;
--text-sm: 13px;
--text-base: 16px;
--text-lg: 20px;
--text-xl: 25px;
--text-2xl: 31px;
--text-3xl: 39px;
--radius-control: 6px;
--radius-card: 12px;
--space-section: 112px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
